print('\n== Task sheet: Row 50 label (cols A-G) and H50..L50 existing ==')
r=50
row_vals = [ws_task.cell(row=r, column=c).value for c in range(1,8)]
print(f'  r50 A-G:', row_vals)
print('  Existing H50-L50:', {col: ws_task[f"{col}50"].value for col in 'HIJKL'})

