        vals=[]
        for c in cols_with_vals:
            v = ws_data.cell(row=r, column=c).value
            if isinstance(v, float):
                vals.append(f'{v:.6g}')
            else:
                vals.append(str(v) if v is not None else '')
        if any(v!='' for v in vals):
            print(f'{r:>4} ' + ' | '.join(f'{v[:10]:>10}' for v in vals))

