for a,b in blocks:
    for r in range(a,b+1):
        code=ws_task[f'D{r}'].value
        if code is not None and str(code).strip()!='':
            series_codes.append(str(code).strip())
series_codes = list(dict.fromkeys(series_codes))
print('Unique series codes from Task blocks:', series_codes)

year_vals = [years[c] for c in 'HIJKL']
print('Year values from Task row10:', year_vals)

# search occurrences
positions_codes = {}
positions_years = {}
for code in series_codes:
    positions_codes[code]=[]
for y in year_vals:
    positions_years[y]=[]

for r in range(min_row, max_row+1):
    for c in cols_with_vals:
        v = ws_data.cell(row=r, column=c).value
        if v is None:
            continue
        sv = str(v).strip()
        if sv in positions_codes:
            positions_codes[sv].append((r,get_column_letter(c)))
        for y in year_vals:
            # numeric vs string matching
            if v==y or sv==str(y):
                positions_years[y].append((r,get_column_letter(c)))

# Print only codes/years that were found
for code, pos in positions_codes.items():
    if pos:
        print(f'  code {code}: {pos}')
for y, pos in positions_years.items():
    if pos:
        print(f'  year {y}: {pos}')
